private string GetStockStatus(int stock, int requested)
{
    if (stock == 0)
        return "Нет в наличии";

    if (requested > stock)
        return "Недостаточно товара";

    if (stock <= 3)
        return "Маленький остаток";

    return "В наличии";
}

