private void RefreshProductsTable()
{
    dgvProducts.Columns.Clear();
    dgvProducts.Rows.Clear();

    dgvProducts.Columns.Add("Name", "Товар");
    dgvProducts.Columns.Add("Manufacturer", "Производитель");
    dgvProducts.Columns.Add("Category", "Категория");
    dgvProducts.Columns.Add("Price", "Цена со скидкой 25%");
    dgvProducts.Columns.Add("Stock", "Остаток");

    foreach (Product item in _products)
    {
        int index = dgvProducts.Rows.Add(
            item.Name, item.Manufacturer, item.Category,
            $"{item.GetDiscountedPrice(25m):N2} ₽", item.Stock);

        dgvProducts.Rows[index].Tag = item;

        if (item.IsLowStock())
        {
            dgvProducts.Rows[index].DefaultCellStyle.BackColor =
                System.Drawing.Color.MistyRose;
        }
    }
}

private void btnShowTable_Click(object sender, EventArgs e)
{
    if (_products.Count == 0)
    {
        MessageBox.Show("Сначала загрузите товары кнопкой каталога");
        return;
